package com.example.qldetai.feature.evaluation;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.List;
public final class EvaluationDtos { private EvaluationDtos(){} public record CriterionRequest(@NotBlank String name,@NotBlank String description,@NotNull @DecimalMin("0.01") @DecimalMax("10.00") BigDecimal maxScore,@Min(1) int sortOrder){} public record CreateRubricRequest(@NotNull Long componentId,@NotBlank String name,@NotEmpty List<CriterionRequest> criteria){} public record CreateEvaluationRequest(@NotNull Long assignmentId,@NotNull Long rubricId,@NotNull Long lecturerId,@NotNull @Future LocalDateTime deadlineAt){} public record ScoreRequest(@NotNull Long criterionId,@NotNull @DecimalMin("0.00") BigDecimal score,String comment){} public record SaveSheetRequest(@NotNull Integer version,String overallComment,@NotEmpty List<ScoreRequest> scores,boolean submit){} public record CriterionResponse(Long id,String name,String description,BigDecimal maxScore,int sortOrder){} public record RubricResponse(Long id,Long componentId,String name,int versionNo,List<CriterionResponse> criteria){} public record ScoreSheetResponse(Long id,Long evaluationId,ScoreSheetStatus status,int version,BigDecimal totalScore,String overallComment,List<ScoreRequest> scores){} }
